        },
        {
          "requirement_id": "S2",
          "status": "satisfied",
          "rationale": "A Notification & Verification service with hexagonal SMS/email adapters and circuit breakers sends codes; expiry is time-tracked. The validity-period inconsistency is a requirement issue.",
          "evidence": [
            "alternatives.json A2.description: 'Notification & Verification' service",
            "alternatives.json A2.selected_patterns: Hexagonal Architecture; Circuit Breaker; Scheduler / Durable Timer"
          ]
        },
        {
          "requirement_id": "S3",
          "status": "partially_satisfied",
          "rationale": "Identity (IAM) service handles password login; the mobile BFF explicitly handles biometric unlock. Thumb-impression disposal is satisfied only under the on-device matching assumption; web-channel biometric behaviour is not addressed.",
          "evidence": [
            "alternatives.json A2.description: 'thin BFFs serve the mobile app (biometric unlock, code scanning, push)'",
            "alternatives.json A2.assumptions: 'Biometric matching occurs on the device (S3 ambiguity).'"
          ]
        },
        {
          "requirement_id": "S4",
          "status": "satisfied",
          "rationale": "Centralized IAM with token-based authentication covers logout and inactivity expiry, with token validation at the gateway. Notifications are produced by Notification & Verification from scheduler events, independent of the biker's session.",
          "evidence": [
            "alternatives.json A2.description: 'An API Gateway is the single entry point for TLS, token validation and rate limiting'",
            "pattern_candidates.json Centralized IAM addressed_concerns: '15-minute inactivity session expiry'",
            "alternatives.json A2.description: 'a durable scheduler in Rental & Fleet emits time-based events'"
          ]
        },
        {
          "requirement_id": "S5",
          "status": "partially_satisfied",
          "rationale": "Proximity queries are served by Rental & Fleet from the authoritative state, so availability is current. The source of bike location data is not allocated beyond an adapter in Rental & Fleet; no ingestion path for bike locations is described.",
          "evidence": [
            "alternatives.json A2.description: 'biker proximity queries are served by Rental & Fleet from the authoritative state'",
            "alternatives.json A2.key_decisions: 'Bike interaction: adapter inside Rental & Fleet service; no dedicated device-ingestion component.'"
